 ExportJob effectJob;auto effectOut=dir.getChildFile("plugin.wav");effectJob.start(s,effectOut,0,48000,32);wait(effectJob);require(std::abs(readWave(effectOut).getSample(0,12000)-0.00025f)<1e-7f,"Single export lost plugin state");++checks;
 auto& hosted=s.engine.getDeviceManager().getHostedAudioDeviceInterface();te::HostedAudioDeviceInterface::Parameters params;params.sampleRate=48000;params.blockSize=128;params.inputChannels=0;params.outputChannels=2;hosted.initialise(params);hosted.prepareToPlay(48000,128);s.save();s.setTrackFrozen(0,true);s.save();
 ExportJob frozen;auto frozenOut=dir.getChildFile("frozen.wav");auto current=s.projectFile;frozen.start(s,frozenOut,0,48000,32);wait(frozen);require(s.projectFile==current&&std::abs(readWave(frozenOut).getSample(0,12000)-0.00025f)<1e-7f,"Single export lost freeze asset or changed path");++checks;
 ExportJob frozenChanged;auto absentFrozen=dir.getChildFile("changed-freeze.wav");frozenChanged.start(s,absentFrozen,0,48000,32);marker(frozenChanged.folder.getChildFile("RENDER_DONE"));auto inputs=juce::JSON::parse(frozenChanged.folder.getChildFile("inputs.json"));bool modified=false;for(auto row:*inputs.getArray()){juce::File file(row["path"].toString());if(file.hasFileExtension("freeze")){char byte=0;require(file.appendData(&byte,1),"Cannot mutate owned freeze asset");modified=true;break;}}require(modified,"Freeze asset was not tracked");refused(frozenChanged,absentFrozen,"input_changed");
 auto mutableRoot=dir.getChildFile("mutable-session");mutableRoot.createDirectory();auto mutableSession=std::make_unique<Session>(mutableRoot);auto media=mutableRoot.getChildFile("owned.wav");require(root.getChildFile("source.wav").copyFileTo(media),"Cannot copy mutable fixture");mutableSession->importAudio(media,0,0);
