 mutableSession=std::make_unique<Session>(mutableRoot);mutableSession->importAudio(media,0,0);
 StemJob changedBatch;auto absentBatch=dir.getChildFile("changed-batch");changedBatch.start(*mutableSession,absentBatch,{0},0,48000);mutableSession.reset();marker(changedBatch.folder.getChildFile("STEMS_DONE"));appendOwned();refused(changedBatch,absentBatch,"input_changed");
 mutableSession=std::make_unique<Session>(mutableRoot);mutableSession->importAudio(media,0,0);
 ExportJob expired;auto noTimed=dir.getChildFile("timeout.wav");expired.start(*mutableSession,noTimed,0,48000*3600,32,1);marker(expired.folder.getChildFile("TIMEOUT"));refused(expired,noTimed,"timed_out");
 StemJob expiredBatch;auto noTimedBatch=dir.getChildFile("timeout-batch");expiredBatch.start(*mutableSession,noTimedBatch,{0},0,48000*3600,false,1);marker(expiredBatch.folder.getChildFile("TIMEOUT"));refused(expiredBatch,noTimedBatch,"timed_out");
 auto localParent=dir.getChildFile("local-plugin");localParent.createDirectory();auto local=localParent.getChildFile(fixture.getFileName());require(fixture.copyDirectoryTo(local),"Cannot copy local plugin fixture");auto localRoot=dir.getChildFile("local-plugin-session");localRoot.createDirectory();Session localSession(localRoot);localSession.importAudio(root.getChildFile("source.wav"),0,0);juce::OwnedArray<juce::PluginDescription> localTypes;format.findAllTypesForFile(localTypes,local.getFullPathName());require(localTypes.size()==1,"Local plugin unavailable");localSession.engine.getPluginManager().initialise();localSession.engine.getPluginManager().knownPluginList.addType(*localTypes[0]);auto localItem=localSession.edit->getPluginCache().createNewPlugin(te::ExternalPlugin::xmlTypeName,*localTypes[0]);localSession.trackAt(0).pluginList.insertPlugin(localItem,0,nullptr);
 ExportJob pluginChanged;auto noPlugin=dir.getChildFile("changed-plugin.wav");pluginChanged.start(localSession,noPlugin,0,48000,32);marker(pluginChanged.folder.getChildFile("RENDER_DONE"));auto resource=local.getChildFile("Contents/Resources/moduleinfo.json");require(resource.existsAsFile()&&resource.appendText(" "),"Cannot mutate owned plugin resource");refused(pluginChanged,noPlugin,"input_changed");

 auto restoredRoot=dir.getChildFile("restored-input-session");restoredRoot.createDirectory();auto restoredSession=std::make_unique<Session>(restoredRoot);auto restoredMedia=restoredRoot.getChildFile("original.wav");require(root.getChildFile("source.wav").copyFileTo(restoredMedia),"Cannot copy restored input");restoredSession->importAudio(restoredMedia,0,0);juce::MemoryBlock originalBytes;require(restoredMedia.loadFileAsData(originalBytes),"Cannot capture restored bytes");auto originalHash=juce::SHA256(restoredMedia).toHexString();auto originalTime=restoredMedia.getLastModificationTime();ExportJob restoredJob;auto noRestored=dir.getChildFile("changed-and-restored.wav");restoredJob.start(*restoredSession,noRestored,0,48000,32);restoredSession.reset();marker(restoredJob.folder.getChildFile("RENDER_DONE"));auto restoredDeadline=juce::Time::getMillisecondCounterHiRes()+5000;while(!restoredMedia.appendData(&byte,1)){require(juce::Time::getMillisecondCounterHiRes()<restoredDeadline,"Cannot mutate restored input");juce::Thread::sleep(10);}require(restoredMedia.replaceWithData(originalBytes.getData(),originalBytes.getSize()),"Cannot restore input bytes");restoredMedia.setLastModificationTime(originalTime);require(juce::SHA256(restoredMedia).toHexString()==originalHash,"Restored bytes differ");refused(restoredJob,noRestored,"input_changed");
 auto parentRoot=dir.getChildFile("parent-watchdog");parentRoot.createDirectory();parentRoot.getChildFile("studio-validation.marker").replaceWithText("isolated parent deadline test");juce::ChildProcess sleeper;RenderGuard parentGuard;parentGuard.start(parentRoot,1);juce::StringArray args{juce::File::getSpecialLocation(juce::File::currentExecutableFile).getFullPathName(),parentRoot.getFullPathName(),"--guard-wait"};require(sleeper.start(args,0)&&sleeper.isRunning(),"Cannot start owned sleeper");juce::Thread::sleep(20);parentGuard.enforce(sleeper);require(sleeper.waitForProcessToFinish(2000),"Timed-out child did not exit");bool timed=false;try{parentGuard.finished(sleeper);}catch(const std::exception&){timed=true;}require(timed&&!sleeper.isRunning()&&parentGuard.failureStatus=="timed_out","Parent deadline failed");++checks;
 auto* report=new juce::DynamicObject;juce::var result(report);report->setProperty("checks",checks);report->setProperty("plugin_state",true);report->setProperty("freeze_assets",true);report->setProperty("media_freeze_plugin_changes_rejected",true);report->setProperty("worker_watchdog_without_parent_poll",true);report->setProperty("parent_deadline",true);report->setProperty("change_then_restore_rejected",true);report->setProperty("device_opened",false);dir.getChildFile("render-guards-result.json").replaceWithText(juce::JSON::toString(result));
